// Family Planner AMP ingest (hybrid: balance + transactions). Mirrors
// app/n8n/bank-ingest.code-node.js (ingestBalancesDir + parseTransactionsCsv,
// source 'AMP'). Reads the mounted scrape folder via fs off the always-present
// Schedule item, so a quiet poll cannot short-circuit before the sentinel.
// Emits items tagged with _target: 'balance' | 'transaction' so the Switch can
// route each to its Firebase writer, OR one { _target:'sentinel' } when there is
// nothing to write. KEEP IN SYNC with bank-ingest.code-node.js.
//
// MOUNT: assumes C:\BankScrapes\amp → /data/bankscrapes/amp.
const fs = require('fs');
const path = require('path');
const ROOT = '/data/bankscrapes/amp';
const CATS = ['banking', 'super', 'investment'];

function validateBalance(o) {
  if (!o || typeof o !== 'object') return false;
  if (typeof o.accountSlug !== 'string' || !o.accountSlug.length) return false;
  if (typeof o.balance !== 'number' || !Number.isFinite(o.balance)) return false;
  if (typeof o.asOf !== 'string' || !o.asOf.length || Number.isNaN(Date.parse(o.asOf))) return false;
  if (typeof o.institution !== 'string' || !o.institution.length) return false;
  if (!CATS.includes(o.category)) return false;
  return true;
}
function parseCsvLine(line) {
  const fields = []; let i = 0;
  while (i <= line.length) {
    if (line[i] === '"') {
      let end = i + 1; while (end < line.length && line[end] !== '"') end++;
      fields.push(line.slice(i + 1, end)); i = end + 1; if (line[i] === ',') i++;
    } else {
      let end = i; while (end < line.length && line[end] !== ',') end++;
      fields.push(line.slice(i, end)); i = end + 1;
    }
  }
  return fields.map(f => f.trim());
}
function parseAmpDate(str) {
  const p = String(str).trim().split('/');
  if (p.length !== 3) return null;
  const day = parseInt(p[0],10), month = parseInt(p[1],10)-1, year = parseInt(p[2],10);
  if (isNaN(day) || isNaN(month) || month < 0 || month > 11 || isNaN(year)) return null;
  return new Date(year, month, day);
}
function parseAmount(str) {
  if (str === undefined || str === null) return null;
  const c = String(str).replace(/[\s",]/g, ''); if (!c.length) return null;
  const n = parseFloat(c); return isNaN(n) ? null : n;
}
function toDateOnly(d) {
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function txKey(tx) {
  return `${tx.dateStr}|${tx.amount}|${tx.details}|${tx.account}`.replace(/[.$#[\]/ -]/g, '_');
}
function listFiles(dir, re, acc) {
  let entries; try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (e) { return acc; }
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) listFiles(full, re, acc);
    else if (re.test(e.name)) acc.push(full);
  }
  return acc;
}

const out = [];
// Balances
for (const file of listFiles(ROOT, /\.balance\.json$/i, [])) {
  let rec; try { rec = JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { continue; }
  if (!validateBalance(rec)) continue;
  out.push({ json: { _target: 'balance', _slug: rec.accountSlug, record: rec } });
}
// Transactions
for (const file of listFiles(ROOT, /\.csv$/i, [])) {
  let text; try { text = fs.readFileSync(file, 'utf8'); } catch (e) { continue; }
  const slug = path.basename(file).replace(/\.csv$/i, '') || 'amp-unknown';
  const lines = text.split(/\r?\n/);
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim(); if (!line) continue;
    const cols = parseCsvLine(line); if (cols.length < 3) continue;
    const date = parseAmpDate(cols[0]); if (!date) continue;
    const amount = parseAmount(cols[2]); if (amount === null) continue;
    const details = cols[1];
    const row = { date: toDateOnly(date), dateStr: cols[0].trim(), amount: Math.abs(amount), isRefund: amount > 0, account: slug, source: 'AMP', txType: '', details, category: '', merchant: details.substring(0,30).trim(), glLine: '', isDuplicate: false };
    out.push({ json: { _target: 'transaction', _key: txKey(row), row } });
  }
}
if (out.length === 0) return [{ json: { _target: 'sentinel' } }];
return out;
